const filtradas = $('Filter - Solo Hoy').all().filter(i => i.json && i.json.ruta);
const resumen = $input.all().filter(i => i.json && i.json.ruta);
const hoy = $now.toFormat('yyyy-LL-dd');

if (filtradas.length === 0) {
  return [{ json: { mensaje: `Resumen diario AndesHogar (${hoy}): no se registraron solicitudes hoy.` } }];
}

let totalMonto = 0;
let totalSolicitudes = 0;
let aprobadas = 0;
const lineas = [];

for (const item of resumen) {
  const ruta = item.json.ruta;
  const cantidad = Number(item.json.count_id_solicitud || 0);
  const montoRuta = Number(item.json.sum_monto || 0);
  totalMonto += montoRuta;
  totalSolicitudes += cantidad;
  if (ruta === 'APROBACION') aprobadas = cantidad;
  lineas.push(`${ruta}: ${cantidad} solicitudes, $${montoRuta.toLocaleString('es-CL')}`);
}

const tasaAprobacion = totalSolicitudes > 0 ? ((aprobadas / totalSolicitudes) * 100).toFixed(1) : '0.0';

const mensaje = `Resumen diario AndesHogar (${hoy})\n` +
  lineas.join('\n') +
  `\nTotal solicitudes: ${totalSolicitudes}` +
  `\nMonto total: $${totalMonto.toLocaleString('es-CL')}` +
  `\nTasa de aprobacion automatica: ${tasaAprobacion}%`;

return [{ json: { mensaje, totalSolicitudes, totalMonto, tasaAprobacion } }];
